import { GoogleGenAI, Type, Modality } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

let lastRequestTimestamp = 0;
const MIN_REQUEST_GAP = 1500;

const throttle = async () => {
  const now = Date.now();
  const timeSinceLast = now - lastRequestTimestamp;
  if (timeSinceLast < MIN_REQUEST_GAP) {
    const waitTime = MIN_REQUEST_GAP - timeSinceLast;
    await new Promise(resolve => setTimeout(resolve, waitTime));
  }
  lastRequestTimestamp = Date.now();
};

export const isAIConfigured = () => {
  return !!process.env.API_KEY && process.env.API_KEY.length > 10;
};

const parseAIResponse = (text: string) => {
  try {
    const cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanText);
  } catch (e) {
    console.error("Failed to parse AI JSON response", e);
    return null;
  }
};

export const generateLessonContent = async (subject: string, topic: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const prompt = `Generate a structured educational lesson for a Nigerian student sitting for the JAMB/UTME exam.
  Subject: ${subject}
  Topic: ${topic}

  The response must be a JSON object with:
  1. theory: A detailed explanation of the concept (Markdown).
  2. examples: 2-3 step-by-step solved problems typical of Nigerian exams (Markdown).
  3. naijaContext: A section explaining how this topic specifically appears in JAMB, common traps for Nigerian students, or local mnemonics.
  4. quiz: An array of 3 multiple-choice questions with options, correct answer index (0-3), and explanation.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: "You are the Head Tutor at MindGrid CramZone. You specialize in the Nigerian JAMB Syllabus. Your explanations are clear, concise, and focused on helping students score 300+ in UTME. Use terms like 'UTME', 'CBT', 'JAMB past questions'.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            theory: { type: Type.STRING },
            examples: { type: Type.STRING },
            naijaContext: { type: Type.STRING },
            quiz: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  answer: { type: Type.INTEGER },
                  explanation: { type: Type.STRING }
                }
              }
            }
          },
          required: ["theory", "examples", "naijaContext", "quiz"]
        }
      }
    });

    return parseAIResponse(response.text || "{}");
  } catch (error) {
    console.error("Lesson Generation Error:", error);
    return null;
  }
};

export const fetchCourseRequirements = async (course: string, university: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const prompt = `Find the 2024/2025 admission requirements for "${course}" at "${university}". 
  Include: 
  1. JAMB Subject Combination.
  2. O-Level (WAEC/NECO) requirements (minimum 5 subjects).
  3. Last known departmental cutoff mark.
  4. Direct Entry requirements if applicable.
  5. Any specific catching area or ELDS considerations.
  Return the data in a clear Markdown format.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are an expert Admissions Consultant for Nigerian Universities. Provide accurate, grounded information for the current academic session. Always cite sources.",
      },
    });

    const text = response.text || "No data found.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Admission Portal',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];

    return { text, sources };
  } catch (error) {
    console.error("Course Finder Error:", error);
    throw error;
  }
};

export const generateFullArticle = async (topic?: string) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();

  const prompt = topic 
    ? `Write a detailed 600-word academic guide for Nigerian students on: "${topic}". 
       Structure: 
       1. Introduction 
       2. Detailed Strategy/Steps 
       3. Local Context (How it applies in Nigeria) 
       4. Final Advice. 
       Use Markdown formatting.`
    : `Choose a random, highly specific trending academic or career topic for Nigerian students. 
       Write a 600-word high-quality guide. Return as JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        systemInstruction: "You are the Lead Editor of the MindGrid Library. You write authoritative, verified, and deeply helpful guides for Nigerian scholars. Return ONLY valid JSON.",
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            excerpt: { type: Type.STRING },
            content: { type: Type.STRING },
            category: { type: Type.STRING }
          },
          required: ["title", "excerpt", "content", "category"]
        }
      }
    });

    return parseAIResponse(response.text || "{}");
  } catch (error) {
    console.error("Discovery Generation Error:", error);
    return null;
  }
};

export const generateStudyHelp = async (query: string, useSearch: boolean = false) => {
  if (!isAIConfigured()) throw new Error("API_KEY_MISSING");
  await throttle();
  try {
    const config: any = {
      systemInstruction: `You are MindGrid AI, an academic mentor for Nigerians. Grounding: JAMB, WAEC, NUC.`,
      temperature: 0.8,
    };
    if (useSearch) config.tools = [{ googleSearch: {} }];
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: query }] }],
      config: config,
    });
    const text = response.text || "Failed to generate response.";
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || 'Source',
      uri: chunk.web?.uri
    })).filter((s: any) => s.uri) || [];
    return { text, sources };
  } catch (error: any) { throw error; }
};

export const fetchRealtimeNews = async (category: string) => {
  if (!isAIConfigured()) return null;
  await throttle();
  const searchCategory = category === 'All' ? 'Nigerian Education News' : `Nigerian ${category} news`;
  const prompt = `Recent student updates for: "${searchCategory}".`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              excerpt: { type: Type.STRING },
              date: { type: Type.STRING },
              url: { type: Type.STRING }
            }
          }
        }
      },
    });
    return parseAIResponse(response.text || "[]");
  } catch (error) { return null; }
};

export const generateAISchedule = async (goal: string) => {
  if (!isAIConfigured()) return null;
  await throttle();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ parts: [{ text: `Study plan for: "${goal}".` }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              day: { type: Type.STRING },
              sessions: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { subject: { type: Type.STRING }, topic: { type: Type.STRING } } } }
            }
          }
        }
      },
    });
    return parseAIResponse(response.text || "[]");
  } catch (error) { return null; }
};

export const textToSpeech = async (text: string) => {
  if (!isAIConfigured()) return null;
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text.substring(0, 1000) }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (e) { return null; }
};

import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { fetchCourseRequirements } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import ShareButton from '../components/ShareButton';

const CourseFinder: React.FC = () => {
  const { showToast } = useToast();
  const [course, setCourse] = useState('');
  const [university, setUniversity] = useState('');
  const [result, setResult] = useState<{ text: string, sources: any[] } | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!course || !university) {
      showToast('Please enter both course and university', 'info');
      return;
    }
    setLoading(true);
    setResult(null);
    try {
      const data = await fetchCourseRequirements(course, university);
      setResult(data);
    } catch (err) {
      showToast('Failed to fetch requirements. Try again.', 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <div className="text-center mb-12">
        <h1 className="text-4xl font-black text-slate-800 mb-4">Admissions <span className="text-green-600">Navigator</span></h1>
        <p className="text-slate-500 font-medium">Find subject combinations and cutoff marks for any Nigerian University.</p>
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-slate-100 mb-12">
        <form onSubmit={handleSearch} className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">Course of Study</label>
            <input 
              type="text" 
              placeholder="e.g. Civil Engineering"
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-4 focus:ring-green-500/10 focus:border-green-500 font-medium"
              value={course}
              onChange={(e) => setCourse(e.target.value)}
            />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black uppercase text-slate-400 ml-2">University Name</label>
            <input 
              type="text" 
              placeholder="e.g. University of Ibadan"
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-4 focus:ring-green-500/10 focus:border-green-500 font-medium"
              value={university}
              onChange={(e) => setUniversity(e.target.value)}
            />
          </div>
          <button 
            type="submit"
            disabled={loading}
            className="md:col-span-2 bg-slate-900 text-white font-black py-4 rounded-2xl hover:bg-green-600 transition-all shadow-xl disabled:opacity-50 flex items-center justify-center gap-3 uppercase text-xs tracking-widest mt-2"
          >
            {loading ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-search"></i>}
            {loading ? 'Searching Admission Portals...' : 'Find Requirements'}
          </button>
        </form>
      </div>

      {result && (
        <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl overflow-hidden animate-in">
          <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
            <div>
              <h2 className="text-xl font-black">{course}</h2>
              <p className="text-green-400 text-sm font-bold">{university}</p>
            </div>
            <ShareButton 
              title={`Admission Requirements for ${course} at ${university}`}
              text="Found the latest subject combination and cutoff marks on MindGrid!"
              variant="outline"
              className="bg-white/10 border-white/20 text-white"
            />
          </div>
          <div className="p-8 md:p-12 prose prose-slate max-w-none 
            prose-h2:text-slate-800 prose-h2:font-black prose-h2:mt-8
            prose-h3:text-green-600 prose-h3:font-black
            prose-p:text-slate-600 prose-p:leading-relaxed
            prose-strong:text-slate-900 prose-strong:font-black
            prose-ul:list-disc prose-ul:pl-6">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
              {result.text}
            </ReactMarkdown>

            {result.sources.length > 0 && (
              <div className="mt-12 pt-8 border-t border-slate-100 not-prose">
                <p className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Verification Sources:</p>
                <div className="flex flex-wrap gap-2">
                  {result.sources.map((s, i) => (
                    <a key={i} href={s.uri} target="_blank" className="bg-slate-50 border border-slate-100 px-4 py-2 rounded-xl text-[10px] font-bold text-slate-600 hover:bg-slate-100 transition-all flex items-center gap-2">
                      <i className="fas fa-external-link-alt text-[8px]"></i> {s.title}
                    </a>
                  ))}
                </div>
              </div>
            )}
          </div>
          <div className="bg-green-50 p-6 text-center">
            <p className="text-[10px] font-black text-green-700 uppercase tracking-widest mb-1">AI Disclaimer</p>
            <p className="text-[10px] text-green-600 font-medium">Always verify with the official University brochure or JAMB CAPS portal.</p>
          </div>
        </div>
      )}

      {loading && (
        <div className="flex flex-col items-center justify-center py-20 space-y-4">
          <div className="flex gap-2">
            <div className="w-3 h-3 bg-green-600 rounded-full animate-bounce"></div>
            <div className="w-3 h-3 bg-green-600 rounded-full animate-bounce delay-100"></div>
            <div className="w-3 h-3 bg-green-600 rounded-full animate-bounce delay-200"></div>
          </div>
          <p className="text-slate-400 font-black text-xs uppercase tracking-widest">Scanning University Bulletins...</p>
        </div>
      )}
    </div>
  );
};

export default CourseFinder;

