import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { STUDY_CATEGORIES, StudyCategory } from '../constants';
import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { LessonContent, SyllabusSubject, SyllabusTopic } from '../types';

const StudyPage: React.FC = () => {
  const { showToast } = useToast();

  // Navigation State
  const [selectedCategory, setSelectedCategory] = useState<StudyCategory | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<SyllabusSubject | null>(null);
  const [selectedTopic, setSelectedTopic] = useState<SyllabusTopic | null>(null);

  // Content State
  const [lesson, setLesson] = useState<LessonContent | null>(null);
  const [loading, setLoading] = useState(false);
  const [quizScore, setQuizScore] = useState<{ [key: number]: number | null }>({});
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [search, setSearch] = useState('');

  const contentRef = useRef<HTMLDivElement>(null);

  const fetchLesson = async (categoryName: string, subjectName: string, topicTitle: string) => {
    setLoading(true);
    setQuizScore({});
    try {
      const data = await generateLessonContent(`${categoryName} - ${subjectName}`, topicTitle);
      if (data) setLesson(data);
      else showToast('Failed to load lesson content.', 'error');
    } catch (err) {
      showToast('Error syncing with academic vault.', 'error');
    } finally {
      setLoading(false);
      contentRef.current?.scrollTo(0, 0);
    }
  };

  useEffect(() => {
    if (selectedCategory && selectedSubject && selectedTopic) {
      fetchLesson(selectedCategory.name, selectedSubject.name, selectedTopic.title);
    }
  }, [selectedTopic]);

  const handleQuizAnswer = (qIdx: number, oIdx: number) => {
    setQuizScore(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  // Category Selection View
  if (!selectedCategory) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 animate-in">
        <div className="text-center mb-16">
          <h1 className="text-5xl font-black text-slate-800 mb-4 tracking-tight">Study <span className="text-green-600">Hub</span></h1>
          <p className="text-slate-500 text-lg font-medium">Choose your study path to begin excellence.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {STUDY_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setSelectedCategory(cat)}
              className="group bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center overflow-hidden relative"
            >
              <div className={`absolute top-0 left-0 w-full h-1.5 ${cat.color}`}></div>
              <div className={`w-20 h-20 ${cat.color} text-white rounded-3xl flex items-center justify-center text-3xl mb-6 shadow-xl transform group-hover:-translate-y-2 group-hover:rotate-3 transition-all`}>
                <i className={`fas ${cat.icon}`}></i>
              </div>
              <h3 className="text-xl font-black text-slate-800 mb-3">{cat.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed">{cat.description}</p>
              <div className="mt-8 flex items-center gap-2 text-green-600 font-bold text-xs uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                Explore Syllabus <i className="fas fa-arrow-right"></i>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Filtered Subjects for Sidebar
  const filteredSubjects = selectedCategory.subjects.map(sub => ({
    ...sub,
    topics: sub.topics.filter(t => t.title.toLowerCase().includes(search.toLowerCase()))
  })).filter(sub => sub.topics.length > 0);

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-slate-50">
      {/* Sidebar */}
      <aside className={`${sidebarOpen ? 'w-80' : 'w-0'} bg-white border-r border-slate-200 transition-all duration-300 flex flex-col h-full relative`}>
        <div className="p-4 border-b border-slate-100">
           <button 
             onClick={() => {
               setSelectedCategory(null);
               setSelectedSubject(null);
               setSelectedTopic(null);
               setLesson(null);
             }}
             className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-green-600 transition-colors mb-4"
           >
             <i className="fas fa-chevron-left"></i> Back to Hub
           </button>
          <div className="relative">
            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>
            <input 
              type="text" 
              placeholder="Search topics..." 
              className="w-full bg-slate-100 rounded-lg pl-8 pr-4 py-2 text-xs outline-none focus:ring-2 focus:ring-green-500 transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-grow overflow-y-auto no-scrollbar p-4 space-y-6">
          {filteredSubjects.map((sub) => (
            <div key={sub.name} className="space-y-2">
              <div className="flex items-center gap-2 text-slate-400 px-2">
                <i className={`fas ${sub.icon} text-[10px]`}></i>
                <span className="text-[10px] font-black uppercase tracking-widest">{sub.name}</span>
              </div>
              <div className="space-y-1">
                {sub.topics.map((topic) => (
                  <button
                    key={topic.id}
                    onClick={() => {
                      setSelectedSubject(sub);
                      setSelectedTopic(topic);
                    }}
                    className={`w-full text-left px-4 py-2.5 rounded-xl text-sm font-medium transition-all ${selectedTopic?.id === topic.id ? 'bg-green-50 text-green-700 shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
                  >
                    {topic.title}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        <button 
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="absolute -right-4 top-1/2 -translate-y-1/2 w-8 h-8 bg-white border border-slate-200 rounded-full shadow-md flex items-center justify-center text-slate-400 hover:text-green-600 z-10"
        >
          <i className={`fas ${sidebarOpen ? 'fa-chevron-left' : 'fa-chevron-right'} text-[10px]`}></i>
        </button>
      </aside>

      {/* Main Content Area */}
      <main ref={contentRef} className="flex-grow overflow-y-auto bg-white">
        {!selectedTopic ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8">
            <div className={`w-24 h-24 ${selectedCategory.color} text-white rounded-[2rem] flex items-center justify-center text-4xl mb-6 shadow-2xl`}>
               <i className={`fas ${selectedCategory.icon}`}></i>
            </div>
            <h2 className="text-3xl font-black text-slate-800 mb-2">{selectedCategory.name} Syllabus</h2>
            <p className="text-slate-400 max-w-sm font-medium">Select a subject and topic from the sidebar to begin your study session.</p>
          </div>
        ) : loading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-4">
            <div className="w-12 h-12 border-4 border-green-600 border-t-transparent rounded-full animate-spin"></div>
            <p className="text-slate-400 font-black text-[10px] uppercase tracking-widest animate-pulse">Syncing Academy Vault...</p>
          </div>
        ) : lesson ? (
          <div className="max-w-4xl mx-auto px-6 py-12 md:px-12 md:py-16 space-y-16 animate-in">
            {/* Header */}
            <header>
              <div className="flex items-center gap-3 mb-4">
                <span className={`text-white text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${selectedCategory.color}`}>
                  {selectedCategory.name}
                </span>
                <span className="text-slate-300 text-[10px] font-bold uppercase tracking-widest">{selectedSubject?.name}</span>
              </div>
              <h1 className="text-4xl md:text-5xl font-black text-slate-900 tracking-tight leading-tight">
                {selectedTopic.title}
              </h1>
            </header>

            {/* Theory */}
            <section className="space-y-6">
              <div className="flex items-center gap-4">
                <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest">Theoretical Framework</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="prose prose-slate md:prose-lg max-w-none 
                prose-h3:font-black prose-h3:text-slate-800 prose-h3:mt-8 
                prose-p:leading-relaxed prose-p:text-slate-600 
                prose-strong:text-slate-900 prose-strong:font-black
                prose-li:text-slate-600">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {lesson.theory}
                </ReactMarkdown>
              </div>
            </section>

            {/* Solved Examples */}
            <section className="bg-slate-50 p-8 md:p-12 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-8">
              <div className="flex items-center gap-4">
                <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest">Mastery Examples</h2>
                <div className="h-px flex-grow bg-slate-200"></div>
              </div>
              <div className="prose prose-slate max-w-none prose-p:text-slate-700 prose-pre:bg-slate-900 prose-pre:text-white">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {lesson.examples}
                </ReactMarkdown>
              </div>
            </section>

            {/* Naija Context */}
            <section className={`${selectedCategory.color} text-white p-8 md:p-12 rounded-[2.5rem] shadow-xl relative overflow-hidden group`}>
              <div className="relative z-10 space-y-6">
                <div className="flex items-center gap-4">
                  <h2 className="text-sm font-black text-white/60 uppercase tracking-widest">Local Insight</h2>
                  <div className="h-px flex-grow bg-white/20"></div>
                </div>
                <div className="text-white/90 text-lg leading-relaxed font-medium">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>
                    {lesson.naijaContext}
                  </ReactMarkdown>
                </div>
              </div>
              <i className="fas fa-lightbulb absolute -right-4 -bottom-4 text-9xl text-white/10 transform -rotate-12 group-hover:scale-110 transition-transform"></i>
            </section>

            {/* Quiz */}
            <section className="space-y-10 pb-20">
              <div className="flex items-center gap-4">
                <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest">Evaluation</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="space-y-12">
                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-6 animate-in">
                    <p className="text-xl font-black text-slate-800 flex gap-4">
                      <span className="text-green-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-green-300";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-green-100 border-green-500 text-green-700";
                          else if (isSelected) style = "bg-red-100 border-red-500 text-red-700";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-50";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-5 rounded-2xl border-2 text-left font-bold transition-all flex items-center gap-4 ${style}`}
                          >
                            <span className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center shrink-0 text-xs">
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                    {quizScore[qIdx] !== undefined && quizScore[qIdx] !== null && (
                      <div className="bg-slate-900 text-white p-6 rounded-2xl animate-in fade-in slide-in-from-top-2">
                        <p className="text-[10px] font-black uppercase text-green-400 tracking-widest mb-2">
                          {quizScore[qIdx] === q.answer ? 'Excellent!' : 'Correction:'}
                        </p>
                        <p className="text-sm leading-relaxed text-slate-300">{q.explanation}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          </div>
        ) : (
          <div className="flex items-center justify-center h-full text-slate-400">
            Internal sync error. Please try another topic.
          </div>
        )}
      </main>
    </div>
  );
};

export default StudyPage;

