import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { STUDY_CATEGORIES, StudyCategory } from '../constants';
import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { LessonContent, SyllabusSubject, SyllabusTopic } from '../types';

const StudyPage: React.FC = () => {
  const { showToast } = useToast();

  // Navigation & Hierarchy State
  const [activeCategory, setActiveCategory] = useState<StudyCategory | null>(null);
  const [mySubjects, setMySubjects] = useState<SyllabusSubject[]>([]);
  const [selectedSubject, setSelectedSubject] = useState<SyllabusSubject | null>(null);
  const [selectedTopic, setSelectedTopic] = useState<SyllabusTopic | null>(null);

  // Custom Subject Modal State
  const [isAddingSubject, setIsAddingSubject] = useState(false);
  const [newSubjectName, setNewSubjectName] = useState('');

  // Content & Interaction State
  const [lesson, setLesson] = useState<LessonContent | null>(null);
  const [loading, setLoading] = useState(false);
  const [quizScore, setQuizScore] = useState<{ [key: number]: number | null }>({});
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [search, setSearch] = useState('');

  const contentRef = useRef<HTMLDivElement>(null);

  // Persistence: Load my subjects for the active category
  useEffect(() => {
    if (activeCategory) {
      const saved = localStorage.getItem(`mindgrid_subjects_${activeCategory.id}`);
      if (saved) {
        setMySubjects(JSON.parse(saved));
      } else {
        setMySubjects(activeCategory.defaultSubjects);
      }
    }
  }, [activeCategory]);

  // Persistence: Save my subjects
  useEffect(() => {
    if (activeCategory && mySubjects.length > 0) {
      localStorage.setItem(`mindgrid_subjects_${activeCategory.id}`, JSON.stringify(mySubjects));
    }
  }, [mySubjects, activeCategory]);

  const fetchLesson = async (categoryName: string, subjectName: string, topicTitle: string) => {
    setLoading(true);
    setQuizScore({});
    try {
      const data = await generateLessonContent(`${categoryName} - ${subjectName}`, topicTitle);
      if (data) setLesson(data);
      else showToast('Failed to load lesson content.', 'error');
    } catch (err) {
      showToast('Error connecting to MindGrid cloud.', 'error');
    } finally {
      setLoading(false);
      contentRef.current?.scrollTo(0, 0);
    }
  };

  useEffect(() => {
    if (activeCategory && selectedSubject && selectedTopic) {
      fetchLesson(activeCategory.name, selectedSubject.name, selectedTopic.title);
    }
  }, [selectedTopic]);

  const addSubject = () => {
    if (!newSubjectName.trim()) return;

    const subject: SyllabusSubject = {
      name: newSubjectName,
      icon: "fa-book-bookmark",
      topics: [
        { id: Math.random().toString(), title: "Introduction to " + newSubjectName },
        { id: Math.random().toString(), title: "Core Concepts" },
        { id: Math.random().toString(), title: "Advanced Theory" },
        { id: Math.random().toString(), title: "Exam Practice" }
      ]
    };

    setMySubjects([...mySubjects, subject]);
    setNewSubjectName('');
    setIsAddingSubject(false);
    showToast(`${newSubjectName} added to your study desk!`, 'success');
  };

  const removeSubject = (name: string) => {
    setMySubjects(mySubjects.filter(s => s.name !== name));
    if (selectedSubject?.name === name) {
      setSelectedSubject(null);
      setSelectedTopic(null);
      setLesson(null);
    }
  };

  const handleQuizAnswer = (qIdx: number, oIdx: number) => {
    setQuizScore(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  // View 1: Track Selection
  if (!activeCategory) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 animate-in">
        <div className="text-center mb-16 space-y-4">
          <h1 className="text-5xl font-black text-slate-900 tracking-tight">Study <span className="text-emerald-600">Section</span></h1>
          <p className="text-slate-500 text-lg font-medium max-w-2xl mx-auto">Select your current academic path or tech goal to access personalized lessons.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {STUDY_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat)}
              className="group bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center overflow-hidden relative"
            >
              <div className={`absolute top-0 left-0 w-full h-2 ${cat.color}`}></div>
              <div className={`w-24 h-24 ${cat.color} text-white rounded-[2rem] flex items-center justify-center text-4xl mb-8 shadow-xl transform group-hover:-translate-y-2 group-hover:rotate-6 transition-all`}>
                <i className={`fas ${cat.icon}`}></i>
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-4">{cat.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed mb-8">{cat.description}</p>
              <div className="mt-auto bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">
                Access Desk <i className="fas fa-arrow-right ml-2"></i>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // View 2: Study Desk (Subjects + Lessons)
  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-white">
      {/* Sidebar */}
      <aside className={`${sidebarOpen ? 'w-85' : 'w-0'} bg-slate-50 border-r border-slate-200 transition-all duration-300 flex flex-col h-full relative`}>
        <div className="p-6 border-b border-slate-200 bg-white">
           <button 
             onClick={() => {
               setActiveCategory(null);
               setSelectedSubject(null);
               setSelectedTopic(null);
               setLesson(null);
             }}
             className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-emerald-600 transition-colors mb-6"
           >
             <i className="fas fa-arrow-left"></i> Change Path
           </button>

          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">My Desk</h2>
            <button 
              onClick={() => setIsAddingSubject(true)}
              className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-600 flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all"
              title="Register Subject"
            >
              <i className="fas fa-plus text-xs"></i>
            </button>
          </div>

          <div className="relative">
            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
            <input 
              type="text" 
              placeholder="Filter topics..." 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 text-xs outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-grow overflow-y-auto no-scrollbar p-4 space-y-6">
          {mySubjects.map((sub) => {
            const isSelected = selectedSubject?.name === sub.name;
            const filteredTopics = sub.topics.filter(t => t.title.toLowerCase().includes(search.toLowerCase()));

            if (filteredTopics.length === 0 && search) return null;

            return (
              <div key={sub.name} className={`rounded-3xl p-2 transition-all ${isSelected ? 'bg-white shadow-sm ring-1 ring-slate-200' : ''}`}>
                <div className="flex items-center justify-between px-3 py-2">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs ${isSelected ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                      <i className={`fas ${sub.icon}`}></i>
                    </div>
                    <span className="text-xs font-black uppercase tracking-widest text-slate-800">{sub.name}</span>
                  </div>
                  <button onClick={() => removeSubject(sub.name)} className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">
                    <i className="fas fa-times text-[10px]"></i>
                  </button>
                </div>

                <div className="mt-2 space-y-1">
                  {filteredTopics.map((topic) => (
                    <button
                      key={topic.id}
                      onClick={() => {
                        setSelectedSubject(sub);
                        setSelectedTopic(topic);
                      }}
                      className={`w-full text-left px-4 py-3 rounded-xl text-xs font-bold transition-all ${selectedTopic?.id === topic.id ? 'bg-emerald-50 text-emerald-700' : 'text-slate-500 hover:bg-slate-100'}`}
                    >
                      {topic.title}
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>

        <button 
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="absolute -right-4 top-1/2 -translate-y-1/2 w-8 h-8 bg-white border border-slate-200 rounded-full shadow-md flex items-center justify-center text-slate-400 hover:text-emerald-600 z-10"
        >
          <i className={`fas ${sidebarOpen ? 'fa-chevron-left' : 'fa-chevron-right'} text-[10px]`}></i>
        </button>
      </aside>

      {/* Subject Adder Modal */}
      {isAddingSubject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl animate-in zoom-in duration-200">
            <h3 className="text-2xl font-black text-slate-800 mb-2">Register Subject</h3>
            <p className="text-slate-500 text-sm mb-8">Enter the name of the {activeCategory?.type === 'academic' ? 'subject' : 'technology'} you want to master.</p>
            <input 
              type="text" 
              autoFocus
              placeholder="e.g. Further Mathematics"
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-6 py-4 outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all font-bold text-slate-800 mb-6"
              value={newSubjectName}
              onChange={(e) => setNewSubjectName(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addSubject()}
            />
            <div className="flex gap-4">
              <button onClick={() => setIsAddingSubject(false)} className="flex-1 py-4 text-xs font-black uppercase text-slate-400 hover:text-slate-600">Cancel</button>
              <button onClick={addSubject} className="flex-1 bg-emerald-600 text-white py-4 rounded-xl font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-200">Add to Desk</button>
            </div>
          </div>
        </div>
      )}

      {/* Main Content Area */}
      <main ref={contentRef} className="flex-grow overflow-y-auto">
        {!selectedTopic ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8 bg-slate-50/30">
            <div className={`w-32 h-32 ${activeCategory.color} text-white rounded-[3rem] flex items-center justify-center text-5xl mb-8 shadow-2xl animate-in`}>
               <i className={`fas ${activeCategory.icon}`}></i>
            </div>
            <h2 className="text-4xl font-black text-slate-900 mb-4">{activeCategory.name} Vault</h2>
            <p className="text-slate-500 max-w-md mx-auto text-lg font-medium leading-relaxed">
              Welcome to your digital study desk. Select a topic from your registered subjects to start learning.
            </p>
            {!mySubjects.length && (
              <button onClick={() => setIsAddingSubject(true)} className="mt-10 bg-emerald-600 text-white px-10 py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95">
                Register First Subject
              </button>
            )}
          </div>
        ) : loading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-6">
            <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest animate-pulse">Consulting MindGrid Archive...</p>
              <p className="text-xs font-bold text-emerald-600 mt-2">Retrieving {selectedTopic.title}</p>
            </div>
          </div>
        ) : lesson ? (
          <div className="max-w-4xl mx-auto px-6 py-12 md:px-12 md:py-20 space-y-20 animate-in">
            {/* Breadcrumb Header */}
            <header className="border-b border-slate-100 pb-12">
              <div className="flex items-center gap-3 mb-6">
                <span className={`text-white text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full ${activeCategory.color}`}>
                  {activeCategory.name}
                </span>
                <i className="fas fa-chevron-right text-[10px] text-slate-300"></i>
                <span className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{selectedSubject?.name}</span>
              </div>
              <h1 className="text-4xl md:text-6xl font-black text-slate-900 tracking-tight leading-tight">
                {selectedTopic.title}
              </h1>
            </header>

            {/* Theory */}
            <section className="space-y-8">
              <div className="flex items-center gap-6">
                <h2 className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.3em]">Knowledge Base</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="prose prose-slate md:prose-lg max-w-none 
                prose-h3:font-black prose-h3:text-slate-900 prose-h3:mt-12
                prose-p:leading-relaxed prose-p:text-slate-600 
                prose-strong:text-slate-900 prose-strong:font-black
                prose-li:text-slate-600 prose-blockquote:border-emerald-500 prose-blockquote:bg-emerald-50/50 prose-blockquote:p-6 prose-blockquote:rounded-2xl">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {lesson.theory}
                </ReactMarkdown>
              </div>
            </section>

            {/* Mastery Examples */}
            <section className="bg-slate-900 p-8 md:p-16 rounded-[4rem] text-white shadow-2xl relative overflow-hidden group">
              <div className="relative z-10 space-y-10">
                <div className="flex items-center gap-6">
                  <h2 className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.3em]">Mastery Examples</h2>
                  <div className="h-px flex-grow bg-white/10"></div>
                </div>
                <div className="prose prose-invert prose-emerald max-w-none 
                  prose-p:text-slate-300 prose-p:text-lg
                  prose-strong:text-white prose-pre:bg-black/40">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>
                    {lesson.examples}
                  </ReactMarkdown>
                </div>
              </div>
              <i className="fas fa-brain absolute -right-12 -bottom-12 text-[15rem] text-white/5 transform -rotate-12 group-hover:scale-110 transition-transform"></i>
            </section>

            {/* Local Context Insight */}
            <section className="bg-emerald-50 border-2 border-emerald-100 p-8 md:p-12 rounded-[3.5rem] relative overflow-hidden group">
              <div className="relative z-10 flex flex-col md:flex-row gap-8 items-start">
                <div className="w-16 h-16 bg-emerald-600 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl shrink-0">
                  <i className="fas fa-lightbulb"></i>
                </div>
                <div className="space-y-4">
                  <h2 className="text-xl font-black text-emerald-900 uppercase tracking-widest">Naija Exam Insight</h2>
                  <div className="text-emerald-800 text-lg leading-relaxed font-medium">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                      {lesson.naijaContext}
                    </ReactMarkdown>
                  </div>
                </div>
              </div>
            </section>

            {/* Evaluation (Quiz) */}
            <section className="space-y-12 pb-32">
              <div className="flex items-center gap-6">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Evaluation Node</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="space-y-16">
                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-8 animate-in">
                    <p className="text-2xl font-black text-slate-900 flex gap-6">
                      <span className="text-emerald-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-emerald-300 hover:shadow-md";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-200";
                          else if (isSelected) style = "bg-red-600 border-red-600 text-white shadow-lg shadow-red-200";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-40 grayscale";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-6 rounded-3xl border-2 text-left font-black transition-all flex items-center gap-5 text-sm ${style}`}
                          >
                            <span className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${hasAnswered && isCorrect ? 'bg-white/20' : 'bg-slate-100'}`}>
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                    {quizScore[qIdx] !== undefined && quizScore[qIdx] !== null && (
                      <div className="bg-slate-50 border border-slate-100 p-8 rounded-[2.5rem] animate-in slide-in-from-top-4">
                        <div className="flex items-center gap-3 mb-4">
                           <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-full ${quizScore[qIdx] === q.answer ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
                             {quizScore[qIdx] === q.answer ? 'Excellent Work' : 'Learning Opportunity'}
                           </span>
                        </div>
                        <p className="text-slate-600 font-medium leading-relaxed">{q.explanation}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              {/* Navigation Footer for Lessons */}
              <div className="pt-20 flex justify-between items-center">
                 <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">End of Session</p>
                 <button 
                  onClick={() => contentRef.current?.scrollTo({ top: 0, behavior: 'smooth' })}
                  className="bg-slate-100 text-slate-400 p-4 rounded-full hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
                 >
                   <i className="fas fa-arrow-up"></i>
                 </button>
              </div>
            </section>
          </div>
        ) : (
          <div className="flex items-center justify-center h-full text-slate-400 font-bold uppercase text-xs tracking-widest">
            Sync error. Select another node.
          </div>
        )}
      </main>
    </div>
  );
};

