import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { STUDY_CATEGORIES, StudyCategory } from '../constants';
import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { LessonContent, SyllabusSubject, SyllabusTopic } from '../types';

const StudyPage: React.FC = () => {
  const { showToast } = useToast();

  // Navigation & Hierarchy State
  const [activeCategory, setActiveCategory] = useState<StudyCategory | null>(null);
  const [mySubjects, setMySubjects] = useState<SyllabusSubject[]>([]);
  const [selectedSubject, setSelectedSubject] = useState<SyllabusSubject | null>(null);
  const [selectedTopic, setSelectedTopic] = useState<SyllabusTopic | null>(null);

  // Modal State
  const [isAddingSubject, setIsAddingSubject] = useState(false);
  const [subjectSearch, setSubjectSearch] = useState('');

  // Content & Interaction State
  const [lesson, setLesson] = useState<LessonContent | null>(null);
  const [loading, setLoading] = useState(false);
  const [quizScore, setQuizScore] = useState<{ [key: number]: number | null }>({});
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [search, setSearch] = useState('');

  const contentRef = useRef<HTMLDivElement>(null);

  // Persistence: Load my subjects for the active category
  useEffect(() => {
    if (activeCategory) {
      const saved = localStorage.getItem(`mindgrid_subjects_${activeCategory.id}`);
      if (saved) {
        setMySubjects(JSON.parse(saved));
      } else {
        // Initial setup for first-time users
        const defaultSet = activeCategory.availableSubjects.slice(0, 3);
        setMySubjects(defaultSet);
      }
    }
  }, [activeCategory]);

  // Persistence: Save my subjects
  useEffect(() => {
    if (activeCategory && mySubjects.length > 0) {
      localStorage.setItem(`mindgrid_subjects_${activeCategory.id}`, JSON.stringify(mySubjects));
    }
  }, [mySubjects, activeCategory]);

  const fetchLesson = async (categoryName: string, subjectName: string, topicTitle: string) => {
    setLoading(true);
    setQuizScore({});
    try {
      const data = await generateLessonContent(`${categoryName} - ${subjectName}`, topicTitle);
      if (data) setLesson(data);
      else showToast('Failed to load lesson content.', 'error');
    } catch (err) {
      showToast('Error connecting to MindGrid cloud.', 'error');
    } finally {
      setLoading(false);
      contentRef.current?.scrollTo(0, 0);
    }
  };

  useEffect(() => {
    if (activeCategory && selectedSubject && selectedTopic) {
      fetchLesson(activeCategory.name, selectedSubject.name, selectedTopic.title);
    }
  }, [selectedTopic]);

  const addSubject = (subject: SyllabusSubject) => {
    if (mySubjects.some(s => s.name === subject.name)) {
      showToast('Subject already on your desk.', 'info');
      return;
    }
    setMySubjects([...mySubjects, subject]);
    setIsAddingSubject(false);
    showToast(`${subject.name} added to your study desk!`, 'success');
  };

  const removeSubject = (name: string) => {
    setMySubjects(mySubjects.filter(s => s.name !== name));
    if (selectedSubject?.name === name) {
      setSelectedSubject(null);
      setSelectedTopic(null);
      setLesson(null);
    }
  };

  const handleQuizAnswer = (qIdx: number, oIdx: number) => {
    setQuizScore(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  // View 1: Track Selection
  if (!activeCategory) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 animate-in">
        <div className="text-center mb-16 space-y-4">
          <h1 className="text-5xl font-black text-slate-900 tracking-tight">Study <span className="text-emerald-600">Section</span></h1>
          <p className="text-slate-500 text-lg font-medium max-w-2xl mx-auto">Select your current academic path or tech goal to access personalized lessons.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {STUDY_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat)}
              className="group bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center overflow-hidden relative"
            >
              <div className={`absolute top-0 left-0 w-full h-2 ${cat.color}`}></div>
              <div className={`w-24 h-24 ${cat.color} text-white rounded-[2rem] flex items-center justify-center text-4xl mb-8 shadow-xl transform group-hover:-translate-y-2 group-hover:rotate-6 transition-all`}>
                <i className={`fas ${cat.icon}`}></i>
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-4">{cat.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed mb-8">{cat.description}</p>
              <div className="mt-auto bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all">
                Access Desk <i className="fas fa-arrow-right ml-2"></i>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Filtered list of subjects for the modal
  const availableToSelect = activeCategory.availableSubjects
    .filter(s => !mySubjects.some(ms => ms.name === s.name))
    .filter(s => s.name.toLowerCase().includes(subjectSearch.toLowerCase()));

  // View 2: Study Desk (Subjects + Lessons)
  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-white">
      {/* Sidebar */}
      <aside className={`${sidebarOpen ? 'w-85' : 'w-0'} bg-slate-50 border-r border-slate-200 transition-all duration-300 flex flex-col h-full relative overflow-hidden`}>
        <div className="p-6 border-b border-slate-200 bg-white">
           <button 
             onClick={() => {
               setActiveCategory(null);
               setSelectedSubject(null);
               setSelectedTopic(null);
               setLesson(null);
             }}
             className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-emerald-600 transition-colors mb-6"
           >
             <i className="fas fa-arrow-left"></i> Change Path
           </button>

          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">My Desk</h2>
            <button 
              onClick={() => setIsAddingSubject(true)}
              className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-600 flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all"
              title="Add Subject to Desk"
            >
              <i className="fas fa-plus text-xs"></i>
            </button>
          </div>

          <div className="relative">
            <i className="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
            <input 
              type="text" 
              placeholder="Filter topics..." 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 text-xs outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-grow overflow-y-auto no-scrollbar p-4 space-y-6">
          {mySubjects.map((sub) => {
            const isSelected = selectedSubject?.name === sub.name;
            const filteredTopics = sub.topics.filter(t => t.title.toLowerCase().includes(search.toLowerCase()));

            if (filteredTopics.length === 0 && search) return null;

            return (
              <div key={sub.name} className={`rounded-3xl p-2 transition-all ${isSelected ? 'bg-white shadow-sm ring-1 ring-slate-200' : ''}`}>
                <div className="flex items-center justify-between px-3 py-2 group/header">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs ${isSelected ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                      <i className={`fas ${sub.icon}`}></i>
                    </div>
                    <span className="text-xs font-black uppercase tracking-widest text-slate-800">{sub.name}</span>
                  </div>
                  <button 
                    onClick={() => removeSubject(sub.name)} 
                    className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover/header:opacity-100"
                  >
                    <i className="fas fa-times text-[10px]"></i>
                  </button>
                </div>

                <div className="mt-2 space-y-1">
                  {filteredTopics.map((topic) => (
                    <button
                      key={topic.id}
                      onClick={() => {
                        setSelectedSubject(sub);
                        setSelectedTopic(topic);
                      }}
                      className={`w-full text-left px-4 py-3 rounded-xl text-xs font-bold transition-all ${selectedTopic?.id === topic.id ? 'bg-emerald-50 text-emerald-700' : 'text-slate-500 hover:bg-slate-100'}`}
                    >
                      {topic.title}
                    </button>
                  ))}
                </div>
              </div>
            );
          })}

          {mySubjects.length === 0 && (
            <div className="text-center py-10">
              <p className="text-xs text-slate-400 font-bold mb-4">Your desk is empty.</p>
              <button 
                onClick={() => setIsAddingSubject(true)}
                className="text-[10px] font-black uppercase tracking-widest text-emerald-600 border border-emerald-100 px-4 py-2 rounded-xl hover:bg-emerald-50 transition-all"
              >
                Add Subjects
              </button>
            </div>
          )}
        </div>

        <button 
          onClick={() => setSidebarOpen(!sidebarOpen)}
          className="absolute -right-4 top-1/2 -translate-y-1/2 w-8 h-8 bg-white border border-slate-200 rounded-full shadow-md flex items-center justify-center text-slate-400 hover:text-emerald-600 z-10"
        >
          <i className={`fas ${sidebarOpen ? 'fa-chevron-left' : 'fa-chevron-right'} text-[10px]`}></i>
        </button>
      </aside>

      {/* Subject Selection Modal */}
      {isAddingSubject && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl animate-in zoom-in duration-200 max-h-[85vh] flex flex-col overflow-hidden">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-3xl font-black text-slate-800">Add Subjects</h3>
                <p className="text-slate-500 text-sm mt-1">Select from the standard {activeCategory.name} curriculum.</p>
              </div>
              <button 
                onClick={() => setIsAddingSubject(false)}
                className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 transition-all"
              >
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="relative mb-8">
              <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-slate-300"></i>
              <input 
                type="text" 
                placeholder="Search subjects..."
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-12 pr-6 py-4 outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all font-bold"
                value={subjectSearch}
                onChange={(e) => setSubjectSearch(e.target.value)}
              />
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {availableToSelect.map((subject) => (
                  <button
                    key={subject.name}
                    onClick={() => addSubject(subject)}
                    className="flex items-center gap-4 p-5 rounded-[1.5rem] border border-slate-100 hover:border-emerald-600 hover:bg-emerald-50/30 transition-all text-left group"
                  >
                    <div className="w-12 h-12 bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white rounded-xl flex items-center justify-center text-slate-400 text-lg transition-all">
                      <i className={`fas ${subject.icon}`}></i>
                    </div>
                    <div>
                      <h4 className="font-black text-slate-800 text-sm">{subject.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{subject.topics.length} Core Topics</p>
                    </div>
                  </button>
                ))}
                {availableToSelect.length === 0 && (
                  <div className="col-span-full py-12 text-center">
                    <i className="fas fa-check-circle text-emerald-100 text-6xl mb-4"></i>
                    <p className="text-slate-400 font-bold">You've added all available subjects for this track!</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main Content Area */}
      <main ref={contentRef} className="flex-grow overflow-y-auto">
        {!selectedTopic ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8 bg-slate-50/30">
            <div className={`w-32 h-32 ${activeCategory.color} text-white rounded-[3rem] flex items-center justify-center text-5xl mb-8 shadow-2xl animate-in`}>
               <i className={`fas ${activeCategory.icon}`}></i>
            </div>
            <h2 className="text-4xl font-black text-slate-900 mb-4">{activeCategory.name} Vault</h2>
