                  <i className="fas fa-lightbulb"></i>
                </div>
                <div className="space-y-4">
                  <h2 className="text-xl font-black text-emerald-900 uppercase tracking-widest">Naija Exam Insight</h2>
                  <div className="text-emerald-800 text-lg leading-relaxed font-medium">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                      {lesson.naijaContext}
                    </ReactMarkdown>
                  </div>
                </div>
              </div>
            </section>

            {/* Evaluation (Quiz) */}
            <section className="space-y-12 pb-32">
              <div className="flex items-center gap-6">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Evaluation Node</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="space-y-16">
                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-8 animate-in">
                    <p className="text-2xl font-black text-slate-900 flex gap-6">
                      <span className="text-emerald-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-emerald-300 hover:shadow-md";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-emerald-600 border-emerald-600 text-white shadow-lg shadow-emerald-200";
                          else if (isSelected) style = "bg-red-600 border-red-600 text-white shadow-lg shadow-red-200";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-40 grayscale";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-6 rounded-3xl border-2 text-left font-black transition-all flex items-center gap-5 text-sm ${style}`}
                          >
                            <span className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${hasAnswered && isCorrect ? 'bg-white/20' : 'bg-slate-100'}`}>
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                    {quizScore[qIdx] !== undefined && quizScore[qIdx] !== null && (
                      <div className="bg-slate-50 border border-slate-100 p-8 rounded-[2.5rem] animate-in slide-in-from-top-4">
                        <div className="flex items-center gap-3 mb-4">
                           <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-full ${quizScore[qIdx] === q.answer ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
                             {quizScore[qIdx] === q.answer ? 'Excellent Work' : 'Learning Opportunity'}
                           </span>
                        </div>
                        <p className="text-slate-600 font-medium leading-relaxed">{q.explanation}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              {/* Navigation Footer for Lessons */}
              <div className="pt-20 flex justify-between items-center">
                 <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">End of Session</p>
                 <button 
                  onClick={() => contentRef.current?.scrollTo({ top: 0, behavior: 'smooth' })}
                  className="bg-slate-100 text-slate-400 p-4 rounded-full hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
                 >
                   <i className="fas fa-arrow-up"></i>
                 </button>
              </div>
            </section>
          </div>
        ) : (
          <div className="flex items-center justify-center h-full text-slate-400 font-bold uppercase text-xs tracking-widest">
            Sync error. Select another node.
          </div>
        )}
      </main>
    </div>
  );
};

