                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-6 md:space-y-8 animate-in">
                    <p className="text-xl md:text-2xl font-black text-slate-900 flex gap-4 md:gap-6">
                      <span className="text-emerald-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-emerald-300 active:scale-95";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-emerald-600 border-emerald-600 text-white shadow-xl shadow-emerald-100";
                          else if (isSelected) style = "bg-red-600 border-red-600 text-white shadow-xl shadow-red-100";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-40 grayscale pointer-events-none";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-5 md:p-6 rounded-2xl md:rounded-3xl border-2 text-left font-black transition-all flex items-center gap-4 text-xs md:text-sm ${style}`}
                          >
                            <span className={`w-8 h-8 md:w-10 md:h-10 rounded-xl flex items-center justify-center shrink-0 ${hasAnswered && isCorrect ? 'bg-white/20' : 'bg-slate-100'}`}>
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                    {quizScore[qIdx] !== undefined && quizScore[qIdx] !== null && (
                      <div className="bg-slate-50 border border-slate-100 p-6 md:p-8 rounded-3xl animate-in slide-in-from-top-4">
                        <div className="flex items-center gap-3 mb-4">
                           <span className={`text-[9px] font-black uppercase px-3 py-1 rounded-full ${quizScore[qIdx] === q.answer ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
                             {quizScore[qIdx] === q.answer ? 'Mastered' : 'Correction'}
                           </span>
                        </div>
                        <p className="text-slate-600 text-sm md:text-base font-medium leading-relaxed">{q.explanation}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          </div>
        ) : (
          <div className="flex items-center justify-center h-full text-slate-400 font-bold uppercase text-[10px] tracking-widest">
            Sync error. Please re-select.
          </div>
        )}
      </main>

      {/* Subject Selection Modal */}
      {isAddingSubject && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center bg-slate-900/60 backdrop-blur-sm p-0 md:p-4">
          <div className="bg-white w-full max-w-2xl rounded-t-[2.5rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl animate-in slide-in-from-bottom md:zoom-in duration-300 max-h-[90vh] flex flex-col overflow-hidden">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl md:text-3xl font-black text-slate-800">Add Subjects</h3>
                <p className="text-slate-500 text-xs md:text-sm mt-1 font-medium">Customize your desk for {activeCategory.name}.</p>
              </div>
              <button 
                onClick={() => setIsAddingSubject(false)}
                className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500"
              >
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="relative mb-6">
              <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-slate-300"></i>
              <input 
                type="text" 
                placeholder="Find a subject..."
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-12 pr-6 py-4 outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all font-bold text-sm"
                value={subjectSearch}
                onChange={(e) => setSubjectSearch(e.target.value)}
              />
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar pb-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {availableToSelect.map((subject) => (
                  <button
                    key={subject.name}
                    onClick={() => addSubject(subject)}
                    className="flex items-center gap-4 p-5 rounded-2xl border border-slate-100 hover:border-emerald-600 hover:bg-emerald-50/50 transition-all text-left group active:scale-95"
                  >
                    <div className="w-12 h-12 bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white rounded-xl flex items-center justify-center text-slate-400 text-lg transition-all">
                      <i className={`fas ${subject.icon}`}></i>
                    </div>
                    <div>
                      <h4 className="font-black text-slate-800 text-sm">{subject.name}</h4>
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{subject.topics.length} Lessons Available</p>
                    </div>
                  </button>
                ))}
                {availableToSelect.length === 0 && (
                  <div className="col-span-full py-12 text-center">
                    <p className="text-slate-400 font-bold text-sm">No more subjects to add!</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

