import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { LessonContent, SyllabusSubject, SyllabusTopic } from '../types';

const StudyPage: React.FC = () => {
  const { showToast } = useToast();

  // Navigation & Hierarchy State
  const [activeCategory, setActiveCategory] = useState<StudyCategory | null>(null);
  const [mySubjects, setMySubjects] = useState<SyllabusSubject[]>([]);
  const [selectedSubject, setSelectedSubject] = useState<SyllabusSubject | null>(null);
  const [selectedTopic, setSelectedTopic] = useState<SyllabusTopic | null>(null);
  const [activeTrackFilter, setActiveTrackFilter] = useState<'All' | 'Python' | 'Web'>('All');

  // Mobile UI States
  const [isAddingSubject, setIsAddingSubject] = useState(false);
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [subjectSearch, setSubjectSearch] = useState('');

  // Content & Interaction State
  const [lesson, setLesson] = useState<LessonContent | null>(null);
  const [loading, setLoading] = useState(false);
  const [quizScore, setQuizScore] = useState<{ [key: number]: number | null }>({});
  const [search, setSearch] = useState('');

  const contentRef = useRef<HTMLDivElement>(null);

  // Persistence: Load my subjects for the active category
  useEffect(() => {
    if (activeCategory) {
      const saved = localStorage.getItem(`mindgrid_subjects_${activeCategory.id}`);
      if (saved) {
        setMySubjects(JSON.parse(saved));
      } else {
        const defaultSet = activeCategory.availableSubjects.slice(0, 3);
        setMySubjects(defaultSet);
      }
    }
  }, [activeCategory]);

  // Persistence: Save my subjects
  useEffect(() => {
    if (activeCategory && mySubjects.length > 0) {
      localStorage.setItem(`mindgrid_subjects_${activeCategory.id}`, JSON.stringify(mySubjects));
    }
  }, [mySubjects, activeCategory]);

  const fetchLesson = async (categoryName: string, subjectName: string, topicTitle: string) => {
    setLoading(true);
    setQuizScore({});
    setIsMobileSidebarOpen(false); // Close sidebar on mobile after selection
    try {
      const data = await generateLessonContent(`${categoryName} - ${subjectName}`, topicTitle);
      if (data) setLesson(data);
      else showToast('Failed to load lesson content.', 'error');
    } catch (err) {
      showToast('Error connecting to MindGrid cloud.', 'error');
    } finally {
      setLoading(false);
      contentRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    if (activeCategory && selectedSubject && selectedTopic) {
      fetchLesson(activeCategory.name, selectedSubject.name, selectedTopic.title);
    }
  }, [selectedTopic]);

  const addSubject = (subject: SyllabusSubject) => {
    if (mySubjects.some(s => s.name === subject.name)) {
      showToast('Already on your desk.', 'info');
      return;
    }
    setMySubjects([...mySubjects, subject]);
    setIsAddingSubject(false);
    showToast(`${subject.name} added!`, 'success');
  };

  const removeSubject = (name: string) => {
    setMySubjects(mySubjects.filter(s => s.name !== name));
    if (selectedSubject?.name === name) {
      setSelectedSubject(null);
      setSelectedTopic(null);
      setLesson(null);
    }
  };

  const handleQuizAnswer = (qIdx: number, oIdx: number) => {
    setQuizScore(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  // Logic to handle track filtering in Tech
  const displayedSubjects = useMemo(() => {
    if (activeCategory?.id !== 'tech' || activeTrackFilter === 'All') return mySubjects;
    return mySubjects.filter(s => s.name.toLowerCase().includes(activeTrackFilter.toLowerCase()));
  }, [mySubjects, activeTrackFilter, activeCategory]);

  const availableToSelect = useMemo(() => {
    if (!activeCategory) return [];
    let base = activeCategory.availableSubjects.filter(s => !mySubjects.some(ms => ms.name === s.name));

    if (activeCategory.id === 'tech' && activeTrackFilter !== 'All') {
      base = base.filter(s => s.name.toLowerCase().includes(activeTrackFilter.toLowerCase()));
    }

    return base.filter(s => s.name.toLowerCase().includes(subjectSearch.toLowerCase()));
  }, [activeCategory, mySubjects, subjectSearch, activeTrackFilter]);

  // View 1: Track Selection
  if (!activeCategory) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12 md:py-20 animate-in">
        <div className="text-center mb-16 space-y-4">
          <div className="inline-block px-4 py-1.5 bg-emerald-100 text-emerald-700 rounded-full text-[10px] font-black uppercase tracking-[0.2em] mb-4">
            Nigerian Education Node
          </div>
          <h1 className="text-4xl md:text-6xl font-black text-slate-900 tracking-tight">Study <span className="text-emerald-600">Hub</span></h1>
          <p className="text-slate-500 text-base md:text-lg font-medium max-w-xl mx-auto leading-relaxed">
            Select an academic track or tech path to begin your personalized learning journey.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 md:gap-8">
          {STUDY_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat)}
              className="group bg-white p-8 md:p-10 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center relative overflow-hidden active:scale-95"
            >
              <div className={`absolute top-0 left-0 w-full h-2 ${cat.color}`}></div>
              <div className={`w-20 h-20 md:w-24 md:h-24 ${cat.color} text-white rounded-[1.8rem] flex items-center justify-center text-3xl md:text-4xl mb-8 shadow-xl transform group-hover:-translate-y-2 group-hover:rotate-6 transition-all`}>
                <i className={`fas ${cat.icon}`}></i>
              </div>
              <h3 className="text-xl md:text-2xl font-black text-slate-800 mb-3">{cat.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed mb-6 font-medium">{cat.description}</p>
