                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-5 md:p-6 rounded-2xl md:rounded-3xl border-2 text-left font-black transition-all flex items-center gap-4 text-xs md:text-sm ${style}`}
