                  <h2 className="text-lg font-black text-emerald-900 uppercase tracking-widest">Industry Insight</h2>
                  <div className="text-emerald-800 text-base md:text-lg leading-relaxed font-medium">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                      {lesson.naijaContext}
                    </ReactMarkdown>
                  </div>
                </div>
              </div>
            </section>

            {/* Evaluation (Quiz) */}
            <section className="space-y-12 pb-24">
              <div className="flex items-center gap-4">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] shrink-0">Skill Check</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="space-y-12 md:space-y-16">
                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-6 md:space-y-8 animate-in">
                    <p className="text-xl md:text-2xl font-black text-slate-900 flex gap-4 md:gap-6">
                      <span className="text-emerald-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-emerald-300 active:scale-95";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-emerald-600 border-emerald-600 text-white shadow-xl shadow-emerald-100";
                          else if (isSelected) style = "bg-red-600 border-red-600 text-white shadow-xl shadow-red-100";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-40 grayscale pointer-events-none";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-5 md:p-6 rounded-2xl md:rounded-3xl border-2 text-left font-black transition-all flex items-center gap-4 text-xs md:text-sm ${style}`}
                          >
                            <span className={`w-8 h-8 md:w-10 md:h-10 rounded-xl flex items-center justify-center shrink-0 ${hasAnswered && isCorrect ? 'bg-white/20' : 'bg-slate-100'}`}>
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        ) : null}
      </main>

      {/* Subject Selection Modal */}
      {isAddingSubject && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center bg-slate-900/60 backdrop-blur-sm p-0 md:p-4">
          <div className="bg-white w-full max-w-2xl rounded-t-[2.5rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl animate-in slide-in-from-bottom md:zoom-in duration-300 max-h-[90vh] flex flex-col overflow-hidden">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl md:text-3xl font-black text-slate-800">Add Roadmap Modules</h3>
                <p className="text-slate-500 text-xs md:text-sm mt-1 font-medium">Select modules for the {activeTrackFilter === 'All' ? activeCategory.name : activeTrackFilter} track.</p>
              </div>
              <button onClick={() => setIsAddingSubject(false)} className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500"><i className="fas fa-times"></i></button>
            </div>

            <div className="relative mb-6">
              <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-slate-300"></i>
              <input 
                type="text" 
                placeholder="Find a module..."
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-12 pr-6 py-4 outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all font-bold text-sm"
                value={subjectSearch}
                onChange={(e) => setSubjectSearch(e.target.value)}
              />
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar pb-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {availableToSelect.map((subject) => (
                  <button
                    key={subject.name}
                    onClick={() => addSubject(subject)}
                    className="flex items-center gap-4 p-5 rounded-2xl border border-slate-100 hover:border-emerald-600 hover:bg-emerald-50/50 transition-all text-left group active:scale-95"
                  >
                    <div className="w-12 h-12 bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white rounded-xl flex items-center justify-center text-slate-400 text-lg transition-all">
                      <i className={`fas ${subject.icon}`}></i>
                    </div>
                    <div className="overflow-hidden">
                      <h4 className="font-black text-slate-800 text-sm truncate">{subject.name}</h4>
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{subject.topics.length} Lessons Available</p>
                    </div>
                  </button>
                ))}
                {availableToSelect.length === 0 && (
                  <div className="col-span-full py-12 text-center text-slate-400 font-bold text-sm">All modules for this track are on your desk!</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudyPage;

export interface NavItem {
  label: string;
  path: string;
  icon?: string;
}

export interface BlogPost {
  id: string;
  title: string;
  excerpt: string;
  category: 'JAMB' | 'WAEC' | 'Scholarship' | 'University' | 'Career' | 'Tech';
  date: string;
  image: string;
}

export interface CareerOpportunity {
  id: string;
  title: string;
  company: string;
  location: string;
  type: string;
  description: string;
}

export interface GradeScale {
  grade: string;
  point: number;
}

export interface SyllabusTopic {
  id: string;
  title: string;
}

export interface SyllabusSubject {
  name: string;
  icon: string;
  topics: SyllabusTopic[];
}

export interface LessonContent {
  subject: string;
  topic: string;
  theory: string;
  examples: string;
  naijaContext: string;
  quiz: {
    question: string;
    options: string[];
    answer: number;
    explanation: string;
  }[];
}

export interface UserProgress {
  topic_id: string;
  completed_at: string;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { STUDY_CATEGORIES, StudyCategory } from '../constants';
import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../services/supabase';
import { LessonContent, SyllabusSubject, SyllabusTopic, UserProgress } from '../types';

const StudyPage: React.FC = () => {
  const { showToast } = useToast();
  const { user } = useAuth();

  // Navigation & Hierarchy State
  const [activeCategory, setActiveCategory] = useState<StudyCategory | null>(null);
  const [mySubjects, setMySubjects] = useState<SyllabusSubject[]>([]);
  const [selectedSubject, setSelectedSubject] = useState<SyllabusSubject | null>(null);
  const [selectedTopic, setSelectedTopic] = useState<SyllabusTopic | null>(null);
  const [activeTrackFilter, setActiveTrackFilter] = useState<'All' | 'Python' | 'Web' | 'Data'>('All');
  const [techTrackLocked, setTechTrackLocked] = useState<boolean>(false);

  // Mobile UI States
  const [isAddingSubject, setIsAddingSubject] = useState(false);
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);
  const [subjectSearch, setSubjectSearch] = useState('');

  // Content & Interaction State
  const [lesson, setLesson] = useState<LessonContent | null>(null);
  const [loading, setLoading] = useState(false);
  const [quizScore, setQuizScore] = useState<{ [key: number]: number | null }>({});
  const [search, setSearch] = useState('');

  // Progress State
  const [completedTopics, setCompletedTopics] = useState<Set<string>>(new Set());
  const [isSavingProgress, setIsSavingProgress] = useState(false);

  const contentRef = useRef<HTMLDivElement>(null);

  // Load User Progress from Database
  useEffect(() => {
    const fetchProgress = async () => {
      if (!user) {
        const localProgress = localStorage.getItem('mindgrid_local_progress');
        if (localProgress) setCompletedTopics(new Set(JSON.parse(localProgress)));
        return;
      }

      const { data, error } = await supabase
        .from('user_progress')
        .select('topic_id')
        .eq('user_id', user.id);

      if (data) {
        setCompletedTopics(new Set(data.map(p => p.topic_id)));
      }
    };
    fetchProgress();
  }, [user]);

  // Persistence: Load my subjects for the active category
  useEffect(() => {
    if (activeCategory) {
      const saved = localStorage.getItem(`mindgrid_subjects_${activeCategory.id}`);
      if (saved) {
        setMySubjects(JSON.parse(saved));
      } else {
        const defaultSet = activeCategory.availableSubjects.slice(0, 3);
        setMySubjects(defaultSet);
      }

      // Special handling for Tech Track persistence
      if (activeCategory.id === 'tech') {
        const savedTrack = localStorage.getItem('mindgrid_selected_tech_track');
        if (savedTrack && savedTrack !== 'All') {
          setActiveTrackFilter(savedTrack as any);
          setTechTrackLocked(true);
        } else {
          setTechTrackLocked(false);
        }
      }
    }
  }, [activeCategory]);

  // Persistence: Save my subjects
  useEffect(() => {
    if (activeCategory && mySubjects.length > 0) {
      localStorage.setItem(`mindgrid_subjects_${activeCategory.id}`, JSON.stringify(mySubjects));
    }
  }, [mySubjects, activeCategory]);

  const fetchLesson = async (categoryName: string, subjectName: string, topicTitle: string) => {
    setLoading(true);
    setQuizScore({});
    setIsMobileSidebarOpen(false); // Close sidebar on mobile after selection
    try {
      const data = await generateLessonContent(`${categoryName} - ${subjectName}`, topicTitle);
      if (data) setLesson(data);
      else showToast('Failed to load lesson content.', 'error');
    } catch (err) {
      showToast('Error connecting to MindGrid cloud.', 'error');
    } finally {
      setLoading(false);
      contentRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  useEffect(() => {
    if (activeCategory && selectedSubject && selectedTopic) {
      fetchLesson(activeCategory.name, selectedSubject.name, selectedTopic.title);
    }
  }, [selectedTopic]);

  const addSubject = (subject: SyllabusSubject) => {
    if (mySubjects.some(s => s.name === subject.name)) {
      showToast('Already on your desk.', 'info');
      return;
    }
    setMySubjects([...mySubjects, subject]);
    setIsAddingSubject(false);
    showToast(`${subject.name} added!`, 'success');
  };

  const removeSubject = (name: string) => {
    setMySubjects(mySubjects.filter(s => s.name !== name));
    if (selectedSubject?.name === name) {
      setSelectedSubject(null);
      setSelectedTopic(null);
      setLesson(null);
    }
  };

  const handleQuizAnswer = (qIdx: number, oIdx: number) => {
    setQuizScore(prev => ({ ...prev, [qIdx]: oIdx }));
  };

  const toggleCompletion = async (topicId: string) => {
    if (isSavingProgress) return;
    setIsSavingProgress(true);

    const isCurrentlyCompleted = completedTopics.has(topicId);
    const newCompletedTopics = new Set(completedTopics);

    if (isCurrentlyCompleted) {
      newCompletedTopics.delete(topicId);
    } else {
      newCompletedTopics.add(topicId);
    }

    try {
      if (user) {
        if (!isCurrentlyCompleted) {
          await supabase.from('user_progress').insert({
            user_id: user.id,
            topic_id: topicId,
            category_id: activeCategory?.id || 'general'
          });
        } else {
          await supabase.from('user_progress').delete().eq('user_id', user.id).eq('topic_id', topicId);
        }
      } else {
        localStorage.setItem('mindgrid_local_progress', JSON.stringify(Array.from(newCompletedTopics)));
      }
      setCompletedTopics(newCompletedTopics);
      showToast(isCurrentlyCompleted ? 'Marked as uncompleted' : 'Lesson completed! Keep it up.', 'success');
    } catch (err) {
      showToast('Progress sync failed.', 'error');
    } finally {
      setIsSavingProgress(false);
    }
  };

  const selectTechTrack = (track: 'Python' | 'Web' | 'Data') => {
    setActiveTrackFilter(track);
    setTechTrackLocked(true);
    localStorage.setItem('mindgrid_selected_tech_track', track);

    // Auto-add the first module of that track if desk is empty
    const trackSubjects = activeCategory?.availableSubjects.filter(s => s.name.toLowerCase().includes(track.toLowerCase())) || [];
    if (mySubjects.length === 0 && trackSubjects.length > 0) {
      setMySubjects([trackSubjects[0]]);
    }
  };

  // Logic to handle track filtering in Tech
  const displayedSubjects = useMemo(() => {
    if (activeCategory?.id !== 'tech' || activeTrackFilter === 'All') return mySubjects;
    return mySubjects.filter(s => s.name.toLowerCase().includes(activeTrackFilter.toLowerCase()));
  }, [mySubjects, activeTrackFilter, activeCategory]);

  const availableToSelect = useMemo(() => {
    if (!activeCategory) return [];
    let base = activeCategory.availableSubjects.filter(s => !mySubjects.some(ms => ms.name === s.name));

    if (activeCategory.id === 'tech' && activeTrackFilter !== 'All') {
      base = base.filter(s => s.name.toLowerCase().includes(activeTrackFilter.toLowerCase()));
    }

    return base.filter(s => s.name.toLowerCase().includes(subjectSearch.toLowerCase()));
  }, [activeCategory, mySubjects, subjectSearch, activeTrackFilter]);

  // Calculate overall track progress
  const trackProgress = useMemo(() => {
    if (!activeCategory) return 0;
    const allTopics = activeCategory.availableSubjects
      .filter(s => activeCategory.id !== 'tech' || activeTrackFilter === 'All' || s.name.toLowerCase().includes(activeTrackFilter.toLowerCase()))
      .flatMap(s => s.topics);

    if (allTopics.length === 0) return 0;
    const completedInTrack = allTopics.filter(t => completedTopics.has(t.id)).length;
    return Math.round((completedInTrack / allTopics.length) * 100);
  }, [activeCategory, activeTrackFilter, completedTopics]);

  // View 1: Track Selection
  if (!activeCategory) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12 md:py-20 animate-in">
        <div className="text-center mb-16 space-y-4">
          <div className="inline-block px-4 py-1.5 bg-emerald-100 text-emerald-700 rounded-full text-[10px] font-black uppercase tracking-[0.2em] mb-4">
            Nigerian Education Node
          </div>
          <h1 className="text-4xl md:text-6xl font-black text-slate-900 tracking-tight">Study <span className="text-emerald-600">Hub</span></h1>
          <p className="text-slate-500 text-base md:text-lg font-medium max-w-xl mx-auto leading-relaxed">
            Select an academic track or tech path to begin your personalized learning journey.
          </p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 md:gap-8">
          {STUDY_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat)}
              className="group bg-white p-8 md:p-10 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center relative overflow-hidden active:scale-95"
            >
              <div className={`absolute top-0 left-0 w-full h-2 ${cat.color}`}></div>
              <div className={`w-20 h-20 md:w-24 md:h-24 ${cat.color} text-white rounded-[1.8rem] flex items-center justify-center text-3xl md:text-4xl mb-8 shadow-xl transform group-hover:-translate-y-2 group-hover:rotate-6 transition-all`}>
                <i className={`fas ${cat.icon}`}></i>
              </div>
              <h3 className="text-xl md:text-2xl font-black text-slate-800 mb-3">{cat.name}</h3>
              <p className="text-slate-500 text-sm leading-relaxed mb-6 font-medium">{cat.description}</p>
              <div className="mt-auto flex items-center gap-2 text-emerald-600 font-black text-[10px] uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">
                Explore Syllabus <i className="fas fa-arrow-right"></i>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // View 2: Tech Track Selection (Prompt)
  if (activeCategory.id === 'tech' && !techTrackLocked) {
    return (
      <div className="max-w-5xl mx-auto px-4 py-12 md:py-20 animate-in">
        <div className="text-center mb-16 space-y-4">
          <button onClick={() => setActiveCategory(null)} className="text-[10px] font-black uppercase text-slate-400 hover:text-emerald-600 mb-4 transition-colors">
            <i className="fas fa-chevron-left mr-2"></i> All Tracks
          </button>
          <h1 className="text-4xl font-black text-slate-900">What do you want to <span className="text-emerald-600">learn?</span></h1>
          <p className="text-slate-500 font-medium">Choose a path to unlock a structured 2026 roadmap.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[
            { id: 'Python', label: 'Python Mastery', icon: 'fa-brands fa-python', color: 'bg-blue-600', desc: 'Core fundamentals, AI/LLMs, and Backend APIs.' },
            { id: 'Web', label: 'Full-Stack Web', icon: 'fa-globe', color: 'bg-indigo-600', desc: 'React, Node.js, and modern full-stack architecture.' },
            { id: 'Data', label: 'Data Analysis', icon: 'fa-chart-pie', color: 'bg-amber-600', desc: 'Pandas, SQL, Visualization, and BI dashboards.' }
          ].map(track => (
            <button
              key={track.id}
              onClick={() => selectTechTrack(track.id as any)}
              className="group bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-2xl transition-all flex flex-col items-center text-center relative active:scale-95"
            >
              <div className={`w-20 h-20 ${track.color} text-white rounded-[1.5rem] flex items-center justify-center text-3xl mb-8 transform group-hover:scale-110 transition-transform`}>
                <i className={`fas ${track.icon}`}></i>
              </div>
              <h3 className="text-2xl font-black text-slate-800 mb-3">{track.label}</h3>
              <p className="text-slate-500 text-sm leading-relaxed font-medium mb-6">{track.desc}</p>
              <div className="mt-auto px-6 py-2 bg-slate-50 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:bg-emerald-600 group-hover:text-white transition-all">
                Select Track
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // View 3: Study Desk
  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-white relative">

      {/* Mobile Drawer Backdrop */}
      {isMobileSidebarOpen && (
        <div 
          className="md:hidden fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[40] transition-opacity animate-in fade-in"
          onClick={() => setIsMobileSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed md:relative z-[50] md:z-10 h-full bg-slate-50 border-r border-slate-200 transition-transform duration-300
        ${isMobileSidebarOpen ? 'translate-x-0 w-[85%] max-w-[320px]' : '-translate-x-full w-[85%] max-w-[320px]'}
        md:translate-x-0 md:w-80 md:flex flex-col
      `}>
        <div className="p-6 border-b border-slate-200 bg-white">
          <div className="flex items-center justify-between mb-6">
            <button 
              onClick={() => {
                if (activeCategory.id === 'tech') setTechTrackLocked(false);
                else setActiveCategory(null);
              }}
              className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-emerald-600 transition-colors"
            >
              <i className="fas fa-chevron-left"></i> {activeCategory.id === 'tech' ? 'Change Track' : 'Change Path'}
            </button>
            <div className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full">
              {trackProgress}% Done
            </div>
          </div>

          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-800">Study Desk</h2>
            <button 
              onClick={() => setIsAddingSubject(true)}
              className="w-10 h-10 rounded-xl bg-emerald-100 text-emerald-600 flex items-center justify-center hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
              title="Add Subject"
            >
              <i className="fas fa-plus text-sm"></i>
            </button>
          </div>

          <div className="relative">
            <i className="fas fa-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
            <input 
              type="text" 
              placeholder="Search topics..." 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 text-xs outline-none focus:ring-2 focus:ring-emerald-500 transition-all font-medium"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-grow overflow-y-auto no-scrollbar p-4 space-y-4">
          {displayedSubjects.map((sub) => {
            const isSelected = selectedSubject?.name === sub.name;
            const filteredTopics = sub.topics.filter(t => t.title.toLowerCase().includes(search.toLowerCase()));
            if (filteredTopics.length === 0 && search) return null;

            return (
              <div key={sub.name} className={`rounded-3xl p-3 transition-all ${isSelected ? 'bg-white shadow-sm ring-1 ring-slate-200' : ''}`}>
                <div className="flex items-center justify-between px-2 mb-2 group/header">
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-xs ${isSelected ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                      <i className={`fas ${sub.icon}`}></i>
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-800 truncate max-w-[120px]">{sub.name.replace('Python: ', '').replace('Web: ', '').replace('Data: ', '')}</span>
                  </div>
                  <button onClick={() => removeSubject(sub.name)} className="text-slate-300 hover:text-red-500 p-1 opacity-0 md:group-hover/header:opacity-100 transition-opacity">
                    <i className="fas fa-times text-[10px]"></i>
                  </button>
                </div>

                <div className="space-y-1">
                  {filteredTopics.map((topic) => {
                    const isCompleted = completedTopics.has(topic.id);
                    return (
                      <button
                        key={topic.id}
                        onClick={() => {
                          setSelectedSubject(sub);
                          setSelectedTopic(topic);
                        }}
                        className={`w-full text-left px-4 py-3 rounded-xl text-xs font-bold transition-all flex items-center justify-between ${selectedTopic?.id === topic.id ? 'bg-emerald-50 text-emerald-700' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                        <span className="truncate pr-2">{topic.title}</span>
                        {isCompleted && <i className="fas fa-check-circle text-emerald-500 shrink-0"></i>}
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}

          {displayedSubjects.length === 0 && (
             <div className="text-center py-12">
               <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">No modules added yet</p>
               <button 
                 onClick={() => setIsAddingSubject(true)}
                 className="mt-4 text-[10px] font-black text-emerald-600 uppercase tracking-widest bg-emerald-50 px-4 py-2 rounded-xl"
               >
                 Add {activeTrackFilter !== 'All' ? activeTrackFilter : ''} Modules
               </button>
             </div>
          )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main ref={contentRef} className="flex-grow overflow-y-auto bg-white relative">

        {/* Floating Mobile Toggle */}
        <button 
          onClick={() => setIsMobileSidebarOpen(true)}
          className="md:hidden fixed bottom-6 left-6 z-[45] w-14 h-14 bg-emerald-600 text-white rounded-2xl shadow-2xl flex items-center justify-center text-xl hover:scale-110 active:scale-95 transition-transform"
        >
          <i className="fas fa-bars-staggered"></i>
        </button>

        {!selectedTopic ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8 bg-slate-50/20">
            <div className={`w-32 h-32 ${activeCategory.color} text-white rounded-[2.5rem] flex items-center justify-center text-5xl mb-8 shadow-2xl animate-bounce-slow`}>
               <i className={`fas ${activeCategory.icon}`}></i>
            </div>
            <h2 className="text-3xl md:text-5xl font-black text-slate-900 mb-4">{activeTrackFilter !== 'All' ? activeTrackFilter : activeCategory.name} Track</h2>
            <p className="text-slate-500 max-w-sm mx-auto text-base md:text-lg font-medium leading-relaxed">
              Your progress is synced to MindGrid Cloud. Select a lesson to continue.
            </p>
          </div>
        ) : loading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-6">
            <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
            <div className="text-center px-6">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] animate-pulse">Consulting MindGrid Archive...</p>
              <p className="text-sm font-bold text-emerald-600 mt-2">Opening {selectedTopic.title}</p>
            </div>
          </div>
        ) : lesson ? (
          <div className="max-w-4xl mx-auto px-4 py-10 md:px-12 md:py-20 space-y-16 md:space-y-24 animate-in pb-40">
            {/* Context Header */}
            <header className="border-b border-slate-100 pb-10">
              <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
                <div className="flex flex-wrap items-center gap-2 md:gap-3">
                  <span className={`text-white text-[9px] font-black uppercase tracking-widest px-3 py-1.5 rounded-full ${activeCategory.color}`}>
                    {activeTrackFilter !== 'All' ? activeTrackFilter : activeCategory.name}
                  </span>
                  <i className="fas fa-chevron-right text-[8px] text-slate-300"></i>
                  <span className="text-slate-400 text-[9px] font-black uppercase tracking-widest">{selectedSubject?.name}</span>
                </div>
                <button 
                  onClick={() => toggleCompletion(selectedTopic.id)}
                  disabled={isSavingProgress}
                  className={`flex items-center gap-2 px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${completedTopics.has(selectedTopic.id) ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-100 text-slate-600 hover:bg-emerald-50'}`}
                >
                  {isSavingProgress ? <i className="fas fa-spinner fa-spin"></i> : <i className={`fas ${completedTopics.has(selectedTopic.id) ? 'fa-check-circle' : 'fa-circle'}`}></i>}
                  {completedTopics.has(selectedTopic.id) ? 'Completed' : 'Mark Complete'}
                </button>
              </div>
              <h1 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tight leading-tight">
                {selectedTopic.title}
              </h1>
            </header>

            {/* Theory */}
            <section className="space-y-8">
              <div className="flex items-center gap-4">
                <div className="h-px flex-grow bg-slate-100"></div>
                <h2 className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.4em] px-4">The Logic Layer</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="prose prose-slate prose-p:text-slate-600 md:prose-lg max-w-none 
                prose-h3:font-black prose-h3:text-slate-900 prose-h3:mt-12
                prose-strong:text-slate-900 prose-strong:font-black
                prose-pre:bg-slate-900 prose-pre:p-6 prose-pre:rounded-3xl prose-pre:shadow-xl
                prose-blockquote:border-emerald-500 prose-blockquote:bg-emerald-50 prose-blockquote:rounded-2xl prose-blockquote:p-6">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {lesson.theory}
                </ReactMarkdown>
              </div>
            </section>

            {/* Mastery Examples */}
            <section className="bg-slate-900 p-8 md:p-16 rounded-[2.5rem] md:rounded-[4rem] text-white shadow-2xl relative overflow-hidden">
              <div className="relative z-10 space-y-10">
                <div className="flex items-center gap-4">
                  <h2 className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.4em] shrink-0">Live Implementations</h2>
                  <div className="h-px flex-grow bg-white/10"></div>
                </div>
                <div className="prose prose-invert prose-emerald max-w-none 
                  prose-p:text-slate-300 prose-p:text-base md:prose-p:text-lg
                  prose-strong:text-white prose-pre:bg-black/50 prose-pre:rounded-2xl prose-pre:border prose-pre:border-white/10">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>
                    {lesson.examples}
                  </ReactMarkdown>
                </div>
              </div>
              <i className="fas fa-microchip absolute -right-12 -bottom-12 text-[15rem] text-white/5 transform rotate-12"></i>
            </section>

            {/* Local Context Insight */}
            <section className="bg-emerald-50 border border-emerald-100 p-8 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] relative overflow-hidden group">
              <div className="relative z-10 flex flex-col md:flex-row gap-8 items-start">
                <div className="w-14 h-14 md:w-16 md:h-16 bg-emerald-600 text-white rounded-2xl flex items-center justify-center text-xl md:text-2xl shadow-xl shrink-0">
                  <i className="fas fa-lightbulb"></i>
                </div>
                <div className="space-y-4">
                  <h2 className="text-lg font-black text-emerald-900 uppercase tracking-widest">Industry Insight</h2>
                  <div className="text-emerald-800 text-base md:text-lg leading-relaxed font-medium">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                      {lesson.naijaContext}
                    </ReactMarkdown>
                  </div>
                </div>
              </div>
            </section>

            {/* Evaluation (Quiz) */}
            <section className="space-y-12">
              <div className="flex items-center gap-4">
                <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] shrink-0">Skill Check</h2>
                <div className="h-px flex-grow bg-slate-100"></div>
              </div>
              <div className="space-y-12 md:space-y-16">
                {lesson.quiz.map((q, qIdx) => (
                  <div key={qIdx} className="space-y-6 md:space-y-8 animate-in">
                    <p className="text-xl md:text-2xl font-black text-slate-900 flex gap-4 md:gap-6">
                      <span className="text-emerald-600">Q{qIdx + 1}.</span> {q.question}
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
                      {q.options.map((opt, oIdx) => {
                        const isSelected = quizScore[qIdx] === oIdx;
                        const isCorrect = oIdx === q.answer;
                        const hasAnswered = quizScore[qIdx] !== undefined && quizScore[qIdx] !== null;

                        let style = "bg-white border-slate-200 text-slate-600 hover:border-emerald-300 active:scale-95";
                        if (hasAnswered) {
                          if (isCorrect) style = "bg-emerald-600 border-emerald-600 text-white shadow-xl shadow-emerald-100";
                          else if (isSelected) style = "bg-red-600 border-red-600 text-white shadow-xl shadow-red-100";
                          else style = "bg-white border-slate-100 text-slate-300 opacity-40 grayscale pointer-events-none";
                        }

                        return (
                          <button
                            key={oIdx}
                            disabled={hasAnswered}
                            onClick={() => handleQuizAnswer(qIdx, oIdx)}
                            className={`p-5 md:p-6 rounded-2xl md:rounded-3xl border-2 text-left font-black transition-all flex items-center gap-4 text-xs md:text-sm ${style}`}
                          >
                            <span className={`w-8 h-8 md:w-10 md:h-10 rounded-xl flex items-center justify-center shrink-0 ${hasAnswered && isCorrect ? 'bg-white/20' : 'bg-slate-100'}`}>
                              {String.fromCharCode(65 + oIdx)}
                            </span>
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </section>

            {/* Completion Footer */}
            <div className="flex justify-center mt-20">
               <button 
                 onClick={() => toggleCompletion(selectedTopic.id)}
                 disabled={isSavingProgress}
                 className={`group flex items-center gap-6 px-12 py-6 rounded-[2rem] font-black uppercase tracking-[0.2em] transition-all transform hover:scale-105 active:scale-95 ${completedTopics.has(selectedTopic.id) ? 'bg-emerald-600 text-white shadow-2xl' : 'bg-slate-900 text-white shadow-xl hover:bg-emerald-600'}`}
               >
                 {completedTopics.has(selectedTopic.id) ? (
                   <>
                     <i className="fas fa-check-double text-2xl"></i>
                     Topic Mastered
                   </>
                 ) : (
                   <>
                     <i className="fas fa-graduation-cap text-2xl group-hover:rotate-12 transition-transform"></i>
                     Mark as Finished
                   </>
                 )}
               </button>
            </div>
          </div>
        ) : null}
      </main>

      {/* Subject Selection Modal */}
      {isAddingSubject && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center bg-slate-900/60 backdrop-blur-sm p-0 md:p-4">
          <div className="bg-white w-full max-w-2xl rounded-t-[2.5rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl animate-in slide-in-from-bottom md:zoom-in duration-300 max-h-[90vh] flex flex-col overflow-hidden">
            <div className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl md:text-3xl font-black text-slate-800">Add Roadmap Modules</h3>
                <p className="text-slate-500 text-xs md:text-sm mt-1 font-medium">Select modules for the {activeTrackFilter === 'All' ? activeCategory.name : activeTrackFilter} track.</p>
              </div>
              <button onClick={() => setIsAddingSubject(false)} className="w-10 h-10 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500"><i className="fas fa-times"></i></button>
            </div>

            <div className="relative mb-6">
              <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-slate-300"></i>
              <input 
                type="text" 
                placeholder="Find a module..."
                className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-12 pr-6 py-4 outline-none focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 transition-all font-bold text-sm"
                value={subjectSearch}
                onChange={(e) => setSubjectSearch(e.target.value)}
              />
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar pb-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {availableToSelect.map((subject) => (
                  <button
                    key={subject.name}
                    onClick={() => addSubject(subject)}
                    className="flex items-center gap-4 p-5 rounded-2xl border border-slate-100 hover:border-emerald-600 hover:bg-emerald-50/50 transition-all text-left group active:scale-95"
                  >
                    <div className="w-12 h-12 bg-slate-50 group-hover:bg-emerald-600 group-hover:text-white rounded-xl flex items-center justify-center text-slate-400 text-lg transition-all">
                      <i className={`fas ${subject.icon}`}></i>
                    </div>
                    <div className="overflow-hidden">
                      <h4 className="font-black text-slate-800 text-sm truncate">{subject.name}</h4>
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{subject.topics.length} Lessons Available</p>
                    </div>
                  </button>
                ))}
                {availableToSelect.length === 0 && (
                  <div className="col-span-full py-12 text-center text-slate-400 font-bold text-sm">All modules for this track are on your desk!</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudyPage;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { STUDY_CATEGORIES, StudyCategory } from '../constants';
import { generateLessonContent } from '../services/geminiService';
import { useToast } from '../context/ToastContext';
import { useAuth } from '../context/AuthContext';
import { supabase } from '../services/supabase';
import { LessonContent, SyllabusSubject, SyllabusTopic } from '../types';

const ROADMAPS = {
  Python: {
    title: "Python Mastery 2026",
    phases: [
      "Setup & Modern Environments (uv, venv)",
      "Core Fundamentals & Type Hinting",
      "Advanced Data Structures & Comprehensions",
      "Functional Programming & Scope",
      "Object-Oriented Mastery (OOP)",
