                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 overflow-hidden shadow-sm transition-all ${isAdmin ? 'border-slate-800 bg-slate-900 text-white' : 'border-blue-500 bg-slate-100 text-slate-800'}`}>
                   {isAdmin ? (
                     <i className="fas fa-user-shield text-xs"></i>
