              <Link
                to="/login"
                onClick={() => setIsOpen(false)}
                className="block px-3 py-2 rounded-md text-base font-medium bg-blue-600 text-white text-center"
              >
                Log In
              </Link>
            )}
          </div>
        </div>
      )}
    </nav>
