import React, { useState } from 'react';
import { supabase } from '../services/supabase';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [message, setMessage] = useState('');

  const { setAdminStatus } = useAuth();
  const { showToast } = useToast();
  const navigate = useNavigate();

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    // Secret Admin Bypass: Hardcoded credentials for MindGrid Admin
    if (email.toLowerCase() === 'admin@mind.grid' && password === '08022857727') {
      setTimeout(() => {
        setAdminStatus(true);
        showToast('Administrative access granted.', 'success');
        setLoading(false);
        navigate('/admin');
      }, 800);
      return;
    }

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({ email, password });
        if (error) throw error;
        setMessage('Check your email for confirmation link!');
        showToast('Account created! Check email.', 'info');
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email, password });
        if (error) throw error;
        showToast('Login successful!', 'success');
        navigate('/ai-hub');
      }
    } catch (error: any) {
      setMessage(error.message);
      showToast(error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto my-20 px-4">
      <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-slate-100 animate-in">
        <div className="text-center mb-8">
          <div className="bg-blue-600 w-16 h-16 rounded-2xl flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-lg shadow-blue-200">
            <i className="fas fa-user-graduate"></i>
          </div>
          <h1 className="text-3xl font-black text-slate-800">{isSignUp ? 'Join MindGrid' : 'Welcome Back'}</h1>
          <p className="text-slate-500 mt-2 font-medium">Empowering your academic journey.</p>
        </div>

        {message && (
          <div className={`p-4 rounded-xl mb-6 text-sm font-bold text-center ${message.includes('Check') ? 'bg-blue-50 text-blue-700 border border-blue-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
            {message}
          </div>
        )}

        <form onSubmit={handleAuth} className="space-y-4">
          <div className="space-y-1">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
            <input 
              type="text" 
              required
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all font-medium"
              placeholder="Email address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1">Password</label>
            <input 
              type="password" 
              required
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all font-medium"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          <button 
            disabled={loading}
            className="w-full bg-slate-950 text-white font-black py-4 rounded-2xl hover:bg-slate-900 transition-all shadow-xl disabled:opacity-50 active:scale-95 mt-4 flex items-center justify-center gap-3"
          >
            {loading ? <i className="fas fa-spinner fa-spin"></i> : null}
            {isSignUp ? 'Create Account' : 'Sign In'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => setIsSignUp(!isSignUp)}
            className="text-sm font-bold text-slate-400 hover:text-blue-600 transition-colors"
          >
            {isSignUp ? 'Already have an account? Log in' : "Don't have an account? Sign up"}
          </button>
        </div>

        <div className="mt-10 pt-6 border-t border-slate-50 text-center">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Safe & Encrypted</p>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useState, useEffect } from 'react';

const CookieConsent: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const consent = localStorage.getItem('mindgrid_cookie_consent');
    if (!consent) {
      const timer = setTimeout(() => setIsVisible(true), 2000);
      return () => clearTimeout(timer);
    }
  }, []);

  const accept = () => {
    localStorage.setItem('mindgrid_cookie_consent', 'true');
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-[100] p-4 pointer-events-none">
      <div className="max-w-4xl mx-auto bg-slate-950 text-white p-6 rounded-2xl shadow-2xl flex flex-col md:flex-row items-center justify-between gap-4 pointer-events-auto border border-white/10">
        <div className="text-sm">
          <p className="font-semibold mb-1">We value your privacy 🍪</p>
          <p className="text-slate-400">We use cookies to enhance your experience, serve personalized ads (via Google AdSense), and analyze our traffic. By clicking "Accept", you consent to our use of cookies.</p>
        </div>
        <div className="flex gap-3 shrink-0">
          <button 
            onClick={accept}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-xl font-bold text-sm transition-colors"
          >
            Accept All
          </button>
        </div>
      </div>
    </div>
  );
};

export default CookieConsent;

import React, { useState, useEffect } from 'react';
import { subscribeToNewsletter } from '../services/dataService';
import { useToast } from '../context/ToastContext';

interface NewsletterModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const NewsletterModal: React.FC<NewsletterModalProps> = ({ isOpen, onClose }) => {
  const { showToast } = useToast();
  const [email, setEmail] = useState('');
  const [platform, setPlatform] = useState<'email' | 'whatsapp'>('email');
  const [interests, setInterests] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const categories = [
    { id: 'JAMB', label: 'JAMB' },
    { id: 'Scholarships', label: 'Scholarships' },
    { id: 'University', label: 'University' },
    { id: 'Tech', label: 'Tech' },
    { id: 'Career', label: 'Careers' }
  ];

  const toggleInterest = (id: string) => {
    setInterests(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    setIsSubmitting(true);
    try {
      const result = await subscribeToNewsletter(email, interests, platform);
      if (result.success) {
        showToast('You are in the Vault! Welcome.', 'success');
        localStorage.setItem('mindgrid_subscribed', 'true');
        onClose();
      } else {
        showToast(result.error || 'Check your connection.', 'error');
      }
    } catch (err) {
      showToast('Connection error.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-end md:items-center justify-center bg-slate-950/60 backdrop-blur-sm animate-in">
      <div 
        className="bg-white w-full md:max-w-xl md:rounded-[3rem] rounded-t-[2.5rem] overflow-hidden shadow-2xl relative animate-in slide-in-from-bottom md:slide-in-from-bottom-0"
        style={{ animationDuration: '0.4s' }}
      >
        <button 
          onClick={onClose}
          className="absolute top-6 right-6 w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 transition-all z-20"
        >
          <i className="fas fa-times"></i>
        </button>

