            <Link to="/login" className="px-5 py-2 bg-white/5 border border-white/10 rounded-lg hover:bg-white/10 transition-colors text-sm font-medium text-white">
              Login
            </Link>
          )}
        </div>

        <div className="md:hidden flex items-center">
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="text-gray-400 hover:text-white p-2"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden fixed top-20 left-0 right-0 bottom-0 bg-[#050505] z-[70] p-8 border-t border-white/5">
          <div className="flex flex-col gap-6">
            {NAV_LINKS.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className="text-xl font-bold text-gray-400 hover:text-blue-500"
              >
                {link.label === 'CramZone' ? 'Study Hub' : link.label}
              </Link>
            ))}
            <div className="pt-8 border-t border-white/5 flex flex-col gap-4">
              {(user || isAdmin) ? (
                 <button onClick={signOut} className="text-left text-xl font-bold text-red-500">Sign Out</button>
              ) : (
                <Link
                  to="/login"
                  onClick={() => setIsOpen(false)}
                  className="bg-blue-600 text-white py-4 rounded-xl text-center font-bold"
                >
                  Login
                </Link>
              )}
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useEffect, Suspense, lazy, useState } from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import CookieConsent from './components/CookieConsent';
import NewsletterModal from './components/NewsletterModal';

// Lazy Loaded Pages
const HomePage = lazy(() => import('./pages/HomePage'));
const BlogPage = lazy(() => import('./pages/BlogPage'));
const LibraryPage = lazy(() => import('./pages/LibraryPage'));
const ToolsPage = lazy(() => import('./pages/ToolsPage'));
const StudyPage = lazy(() => import('./pages/StudyPage'));
const CGPACalculator = lazy(() => import('./pages/CGPACalculator'));
const TimetablePlanner = lazy(() => import('./pages/TimetablePlanner'));
const CourseFinder = lazy(() => import('./pages/CourseFinder'));
const AIHub = lazy(() => import('./pages/AIHub'));
const CareersPage = lazy(() => import('./pages/CareersPage'));
const AboutPage = lazy(() => import('./pages/AboutPage'));
const ContactPage = lazy(() => import('./pages/ContactPage'));
const PrivacyPage = lazy(() => import('./pages/PrivacyPage'));
const TermsOfService = lazy(() => import('./pages/TermsOfService'));
const LoginPage = lazy(() => import('./pages/LoginPage'));
const NewsletterPage = lazy(() => import('./pages/NewsletterPage'));
const AdminDashboard = lazy(() => import('./pages/AdminDashboard'));

// Loading Fallback updated to Pitch Black
const PageLoader = () => (
  <div className="min-h-screen flex flex-col items-center justify-center bg-[#050505]">
    <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
    <p className="text-blue-400 font-black text-xs uppercase tracking-[0.3em]">Syncing MindGrid...</p>
  </div>
);

const TitleManager: React.FC = () => {
  const location = useLocation();

  useEffect(() => {
    const titles: { [key: string]: string } = {
      '/': 'MindGrid | Nigerian Student Hub & AI Tutor',
      '/study': 'Study Hub | JAMB, WAEC & Tech Mastery | MindGrid',
      '/blog': 'Latest News & Social Buzz | MindGrid Nigeria',
      '/library': 'AI Curated Academic Library | MindGrid Nigeria',
      '/tools': 'Student Power Tools | MindGrid Nigeria',
      '/tools/cgpa': 'Nigerian CGPA Calculator (5.0 & 4.0) | MindGrid',
      '/tools/timetable': 'AI Study Timetable Planner | MindGrid',
      '/tools/course-finder': 'Admissions Navigator | Subject Combination & Cutoffs',
      '/ai-hub': 'AI Study Assistant & Tutor | MindGrid',
      '/careers': 'Student Jobs & Tech Internships Nigeria | MindGrid',
      '/newsletter': 'MindGrid Intelligence | Academic Newsletter',
      '/admin': 'Admin Control | MindGrid Nigeria',
      '/about': 'About MindGrid | Empowering Nigerian Students',
      '/contact': 'Contact Us | MindGrid Support',
      '/privacy': 'Privacy Policy | MindGrid Nigeria',
      '/terms': 'Terms of Service | MindGrid Nigeria',
      '/login': 'Login | Join MindGrid Nigeria',
    };

    document.title = titles[location.pathname] || 'MindGrid | Nigerian Student Resource Hub';
    window.scrollTo(0, 0);
  }, [location]);

  return null;
};

const App: React.FC = () => {
  const [isNewsletterOpen, setIsNewsletterOpen] = useState(false);

  useEffect(() => {
    const hasSubscribed = localStorage.getItem('mindgrid_subscribed');
    const hasBeenPrompted = sessionStorage.getItem('mindgrid_prompted');

    if (!hasSubscribed && !hasBeenPrompted) {
      const timer = setTimeout(() => {
        setIsNewsletterOpen(true);
        sessionStorage.setItem('mindgrid_prompted', 'true');
      }, 10000);
      return () => clearTimeout(timer);
    }
  }, []);

  return (
    <Router>
      <TitleManager />
      <div className="flex flex-col min-h-screen bg-[#050505]">
        <Navbar onOpenNewsletter={() => setIsNewsletterOpen(true)} />
        <main className="flex-grow">
          <Suspense fallback={<PageLoader />}>
            <Routes>
              <Route path="/" element={<HomePage />} />
              <Route path="/study" element={<StudyPage />} />
              <Route path="/blog" element={<BlogPage />} />
              <Route path="/library" element={<LibraryPage />} />
              <Route path="/tools" element={<ToolsPage />} />
              <Route path="/tools/cgpa" element={<CGPACalculator />} />
              <Route path="/tools/timetable" element={<TimetablePlanner />} />
              <Route path="/tools/course-finder" element={<CourseFinder />} />
              <Route path="/ai-hub" element={<AIHub />} />
              <Route path="/careers" element={<CareersPage />} />
              <Route path="/newsletter" element={<NewsletterPage />} />
              <Route path="/admin" element={<AdminDashboard />} />
              <Route path="/about" element={<AboutPage />} />
              <Route path="/contact" element={<ContactPage />} />
              <Route path="/privacy" element={<PrivacyPage />} />
              <Route path="/terms" element={<TermsOfService />} />
              <Route path="/login" element={<LoginPage />} />
            </Routes>
          </Suspense>
        </main>
        <Footer onOpenNewsletter={() => setIsNewsletterOpen(true)} />
        <CookieConsent />
        <NewsletterModal isOpen={isNewsletterOpen} onClose={() => setIsNewsletterOpen(false)} />
      </div>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Cpu, Menu, X } from 'lucide-react';
import { NAV_LINKS } from '../constants';
import { useAuth } from '../context/AuthContext';

interface NavbarProps {
  onOpenNewsletter: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onOpenNewsletter }) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();
  const { user, isAdmin, signOut } = useAuth();

  return (
    <nav className="bg-[#050505] border-b border-white/5 sticky top-0 z-[60] h-20 flex items-center" role="navigation" aria-label="Main Navigation">
      <div className="max-w-7xl mx-auto px-8 w-full flex justify-between items-center">
        <div className="flex items-center">
          <Link to="/" className="flex items-center gap-2 group" aria-label="MindGrid Home">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform">
              <Cpu size={24} className="text-white" />
            </div>
            <span className="text-2xl font-bold tracking-tight text-white">
              Mind<span className="text-blue-500">Grid</span>
            </span>
          </Link>
        </div>

        <div className="hidden md:flex items-center space-x-8">
          {NAV_LINKS.map((link) => (
            link.path === '/newsletter' ? (
              <button
                key={link.path}
                onClick={onOpenNewsletter}
                className="text-gray-400 hover:text-blue-400 text-sm font-medium transition-colors"
                aria-label={`Open ${link.label}`}
              >
                {link.label}
              </button>
            ) : (
              <Link
                key={link.path}
                to={link.path}
                className={`${
                  location.pathname === link.path
                    ? 'text-blue-500'
                    : 'text-gray-400 hover:text-blue-400'
                } text-sm font-medium transition-colors`}
                aria-current={location.pathname === link.path ? 'page' : undefined}
              >
                {link.label === 'CramZone' ? 'Study Hub' : link.label}
              </Link>
            )
          ))}

          {isAdmin && (
            <Link
              to="/admin"
              className="text-gray-400 hover:text-blue-400 text-sm font-bold uppercase tracking-widest flex items-center gap-2"
              aria-label="Admin Dashboard"
            >
              Admin
            </Link>
          )}

          {(user || isAdmin) ? (
            <div className="flex items-center gap-6">
              <button 
                onClick={signOut}
                className="text-gray-500 hover:text-red-500 text-xs font-bold uppercase transition-colors"
                aria-label="Sign out"
              >
                Log Out
              </button>
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center border border-white/10 shadow-xl transition-all ${isAdmin ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white'}`} aria-hidden="true">
                 <span className="font-black text-xs uppercase">{user?.email?.substring(0, 2)}</span>
              </div>
            </div>
          ) : (
            <Link to="/login" className="px-5 py-2 bg-white/5 border border-white/10 rounded-lg hover:bg-white/10 transition-colors text-sm font-medium text-white" aria-label="Login to account">
              Login
            </Link>
          )}
        </div>

        <div className="md:hidden flex items-center">
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="text-gray-400 hover:text-white p-2"
            aria-expanded={isOpen}
            aria-label="Toggle menu"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden fixed top-20 left-0 right-0 bottom-0 bg-[#050505] z-[70] p-8 border-t border-white/5 animate-in slide-in-from-top-4">
          <div className="flex flex-col gap-6">
            {NAV_LINKS.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className="text-xl font-bold text-gray-400 hover:text-blue-500"
              >
                {link.label === 'CramZone' ? 'Study Hub' : link.label}
              </Link>
            ))}
            <div className="pt-8 border-t border-white/5 flex flex-col gap-4">
              {(user || isAdmin) ? (
                 <button onClick={signOut} className="text-left text-xl font-bold text-red-500">Sign Out</button>
              ) : (
                <Link
                  to="/login"
                  onClick={() => setIsOpen(false)}
                  className="bg-blue-600 text-white py-4 rounded-xl text-center font-bold"
                >
                  Login
                </Link>
              )}
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

